insert into public.lore_entries (slug, title, category, content, pathway, epoch, city, npcs, sequences, tags, token_count)
values
  ('npc-kircheis', 'Kircheis — Slaughterer', 'npc', 'Slaughterer Kircheis was a notorious pirate and the second mate of Agalito, the King of Immortality. He served aboard the Death Announcer and carried a bounty of 9,500 pounds. A human man with brown eyes, a medium build, and purple lips, he tried to conceal an intense baneful look. Kircheis was a Sequence 5 Desire Apostle of the Abyss Pathway. In Nas in the Gargas Archipelago, he was pursuing an adventurer when the man fled into the Lærdal Bar for help from the Adventurer Association. There Kircheis recognized Gehrman Sparrow and warned him not to interfere, saying that the matter was Agalito''s will. They met again in a bar on Toscarter Island. Gehrman acted immediately and grazed Kircheis''s soul with Creeping Hunger. After Kircheis died, Klein collected the blood crystal his body produced and called it the Aura of Blatherer. The page records his death in April 1350 and identifies Gehrman Sparrow as the one who killed him.', null, 5, null, ARRAY['Kircheis'], ARRAY[5], ARRAY['abyss-pathway', 'pirate', 'death-announcer', 'deceased', 'book-one'], 205),
  ('npc-squall', 'Squall — Calm Squall', 'npc', 'Calm Squall was the chief helper of Steel Maveti and a pirate of the Tree of Flesh and Blood Pirates. He was a human man and a Sequence 8 Unwinged Angel of the Abyss Pathway, carrying a bounty of 1,500 pounds. Squall was good at controlling his emotions and thinking calmly, but the account also calls him inhumane. He stood about 1.78 meters tall and wore a boat-shaped hat. His face was thin and sharp, with an aggressive expression; a lock of black hair fell over the dark-green eye on his left side and softened his coldness. Steel Maveti and Blood Brambles Hendry are listed as his allies. His equipment included a batch of scalps and a Shriek Charm. In the recorded events, Squall met Alger in order to obtain information about Danitz. The page identifies Gehrman Sparrow as his killer and places his death at Book One chapter 527. Though his description is brief, it fixes him as Maveti''s chief helper rather than a captain in his own right.', null, 5, null, ARRAY['Squall'], ARRAY[8], ARRAY['abyss-pathway', 'pirate', 'tree-of-flesh-and-blood-pirates', 'deceased', 'book-one'], 182),
  ('npc-maveti', 'Maveti — Steel Maveti', 'npc', 'Steel Maveti was the second mate of Senor, the Admiral of Blood, and a pirate affiliated with both the Rose School of Thought and the Tree of Flesh and Blood Pirates. He was a human man, a Sequence 6 Zombie of the Chained Pathway, with a bounty of 6,000 pounds. Calm Squall and Blood Brambles Hendry were named as his allies. Maveti had thick lips, swarthy skin, and hair curled like the steel balls seen in factories. His arm muscles trembled with great strength, yet his whole presence felt cold and sinister, as though he were not a living creature. When Danitz entered Bayam, Maveti attacked him over the rumored Death''s Key. Klein Moretti, acting as Gehrman Sparrow, had Danitz locate Maveti and set a trap; Alger Wilson then offered help through the Mandated Punishers. Gehrman killed Steel Maveti, and Creeping Hunger grazed his soul. The corpus consequently presents him as a dangerous pirate subordinate whose pursuit of the rumored key ended in that ambush.', null, 5, null, ARRAY['Maveti'], ARRAY[6], ARRAY['chained-pathway', 'zombie', 'pirate', 'rose-school-of-thought', 'deceased', 'book-one'], 184),
  ('npc-eric', 'Eric — Red Gloves Captain', 'npc', 'Eric is a human man from Midseashire in the Loen Kingdom and the captain of a Red Gloves team. He is affiliated with the Red Gloves and the Church of the Evernight Goddess, and is a Sequence 5 Spirit Warlock of the Darkness Pathway. Before becoming captain, Eric witnessed the deaths of the previous two captains during the war, then advanced to Sequence 5 and was promoted during the war''s later stages. The archbishop of the Midseashire diocese later entrusted Eric''s team with the matter concerning the apartment at 14 Priya Street, and authorized them to apply for a Grade 1 Sealed Artifact as support. Eric led the team into Unit 403, where policemen and two Nighthawks had previously gone missing. When the group found themselves in peril, the wandering magician Merlin Hermes rescued them. Eric asked Merlin to resolve the abnormalities in Unit 403. Their investigation revealed the room''s connection to an academic organization called the Celestial Research Association and to the Cosmos. Eric is recorded as alive.', null, 5, null, ARRAY['Eric'], ARRAY[5], ARRAY['darkness-pathway', 'spirit-warlock', 'red-gloves', 'nighthawks', 'church-of-evernight', 'book-one'], 183),
  ('npc-davy-raymond', 'Davy Raymond — Red Glove', 'npc', 'Davy Raymond was a Red Glove of the Nighthawks and a follower of the Church of the Evernight Goddess. A human man from Desi County, he was a Sequence 7 Nightmare of the Darkness Pathway. He had black hair, blue eyes, a long thin face, marked nasolabial folds, and a light beard around his mouth and chin. Davy had a daughter, Neelu Raymond; his wife was already dead. He lost his parents, wife, and siblings in a black-magic incident, leaving Neelu as his only family. He joined the Nighthawks to investigate that incident and later became a Red Glove. While tracking ancient Balam chronicles, Davy''s team encountered Qilangos. They might have escaped and killed him through teamwork, but their ship sank and they took to a lifeboat; everyone died in the line of duty. Creeping Hunger grazed Davy''s soul. After Klein freed that soul, Davy''s last concern was Neelu. He asked Klein to tell her the culprits had been punished, that his death was an accident, and that her father loved her and was sorry for neglecting her.', null, 5, null, ARRAY['Davy Raymond'], ARRAY[7], ARRAY['darkness-pathway', 'nightmare', 'red-gloves', 'nighthawks', 'deceased', 'book-one'], 191),
  ('npc-verdu-garcia', 'Verdu Garcia Abraham — Astrologer', 'npc', 'Verdu Garcia Abraham was a direct member of the Abraham Family, a human man of the Northern Continent, and a Sequence 7 Astrologer of the Door Pathway. He wore gold-rimmed glasses and resembled a university professor. Verdu studied many kinds of mysticism in hopes of finding a complete solution to the Abraham Family''s curse. After learning the truth of that curse, he instead wished to help his ancestor, Mr. Door, return to the real world. He left the Northern Continent for the Rorsted Archipelago, away from Dorian and other family members, so that he could focus on his research. Dorian reported the move to the Fool, who assigned Alger Wilson to monitor Verdu. During the next half year Verdu planned to leave Bayam for East Balam, but news about Bansy Harbor heard at a gathering changed his course. He hired a ship for Bansy. Medici and Amon deceived him into conducting the ritual that released Mr. Door from banishment. When it succeeded and the Door of Flesh and Blood appeared, Verdu died as his body slowly collapsed, before he understood why.', null, 5, null, ARRAY['Verdu Garcia Abraham'], ARRAY[7], ARRAY['door-pathway', 'astrologer', 'abraham-family', 'deceased', 'book-one'], 235),
  ('npc-jodeson', 'Jodeson — Flowery Bow Tie', 'npc', 'Jodeson, called Flowery Bow Tie Jodeson, is a human pirate and the Third Mate of the Golden Dream Pirates. He is a Sequence 6 Prometheus of the Error Pathway, is about thirty years old, and has a bounty of 5,200 pounds. His allies and affiliation are both recorded as the Golden Dream Pirates. He dresses in a white shirt and black vest with a flowery bow tie, looking more like an office worker than a pirate. His hair is black at the roots but dyed blond and carefully combed to either side; his light lake-green eyes, sharp nose, and thin lips give him a trustworthy air. Before joining the Golden Dream, Jodeson was a casanova and a part-time pirate. He claimed he would steal Edwina Edwards''s heart, but she beat him instead. He then stayed with the Golden Dream Pirates to be educated. Later, Klein Moretti sought Jodeson''s help in finding a Sealed Artifact of the Error Pathway. The corpus supplies no further outcome for that search, but it clearly identifies Jodeson by his third-mate role, his nickname, and the rank he held on the Error Pathway.', null, 5, null, ARRAY['Jodeson'], ARRAY[6], ARRAY['error-pathway', 'prometheus', 'golden-dream-pirates', 'pirate', 'book-one'], 243),
  ('npc-heath-doyle', 'Heath Doyle — Bloodless Heath', 'npc', 'Bloodless Heath Doyle is a human pirate, the second mate of the Future under its captain, the Admiral of Stars Cattleya. He belongs to the Stars Pirates, is friends with Frank Lee, and carries a bounty of 7,600 pounds. Heath is a Sequence 6 Rose Bishop of the Hanged Man Pathway. His cheeks are nearly transparent, his nose bridge is unusually tall, and his whole appearance is sickly. An incident scattered the potion brewed from Rose Bishop Beyonder ingredients over him. The potion seeped into him gradually; he survived and became a Sequence 6 Beyonder in one step. Because he never passed through the Listener stage, he was neither tainted nor driven mad. The account states that he remains an ordinary person as long as he does not deliberately use the Beyonder power Listen. To restrain that power, he possesses a Sealed Artifact whose drawback is that he can hear only nearby voices. The page''s sequence-progression record further says he first appeared already at Rose Bishop, becoming a Beyonder directly at that sequence. The corpus records Heath as alive in both Book One and Book Two fields.', null, 5, null, ARRAY['Heath Doyle'], ARRAY[6], ARRAY['hanged-man-pathway', 'rose-bishop', 'stars-pirates', 'pirate', 'book-one', 'book-two'], 243),
  ('npc-hendry', 'Hendry — Blood Brambles', 'npc', 'Blood Brambles Hendry was a pirate of the Tree of Flesh and Blood Pirates, identified as Maveti''s deputy for a particular round of operations. The corpus also calls him captain of the sixth ship, which was lost in the battle against Vice Admiral Dusk. His listed associates were Steel Maveti and Calm Squall, linking him to the same pirate group rather than establishing an independent crew. Hendry carried a bounty of 3,800 pounds. He was a male human and a Sequence 7 Warlock; the corpus records that rank directly. His alias is Blood Brambles, and the source labels his occupation simply as pirate. In appearance, he wore a brown local tunic and twirled a yellowish-brown straw hat on his fingers. His listed equipment consisted of a Flying Carpet and Sea Waves powder. Hendry was killed by Danitz Dubois. The source provides no further history for him, so his dossier should remain confined to those recorded associations, equipment, the lost sixth ship, and his death.', null, 5, null, ARRAY['Hendry'], ARRAY[7], ARRAY['book-one', 'pirate', 'tree-of-flesh-and-blood-pirates', 'deceased', 'sequence-7'], 184),
  ('npc-andy-haydn', 'Andy Haydn — Enmat''s Second Mate', 'npc', 'Andy Haydn was the Second Mate of the Enmat and held the naval rank of Commander. A male human in his thirties, he wore a navy uniform and had brown whiskers on a face described as painful and dazed. The corpus identifies him directly as a Sequence 7 Interrogator of the Justiciar Pathway. Andy died in the Konotop Sea battle of 1338, in the Fifth Epoch. During that battle, he was captured by a Feysacian and then grazed by Creeping Hunger. The corpus does not name a killer. Later, Klein Moretti freed Andy from Creeping Hunger. This appearance is explicitly tied to that release, rather than to an account of Andy returning to naval service or taking part in later events. His recorded military position, berth on the Enmat, and death at Konotop are therefore the secure frame for the character. The source gives neither a residence nor an affiliation beyond these duties, and it supplies no alias, relatives, or further biographical history. His entry should not extend beyond the documented wartime capture, the artifact''s effect, and Klein''s intervention.', null, 5, null, ARRAY['Andy Haydn'], ARRAY[7], ARRAY['book-one', 'enmat', 'naval-officer', 'konotop-sea-battle', 'deceased', 'sequence-7'], 191),
  ('npc-wendel', 'Wendel — MI9 Internal Affairs Officer', 'npc', 'Wendel is a male human member of MI9''s internal affairs department and a Sequence 7 Interrogator of the Justiciar Pathway. Before joining MI9, he served as a Feynapotter intelligence officer active in Desi Bay; his contributions there led to his promotion to Sequence 7 and his present internal-affairs post. He has deep-black sideburns and calm brown eyes, no memorable individual features, but exudes comfortable vibes. Wendel was assigned to carry Alfred Hall''s confidential document from Desi Bay to MI9''s director in Backlund. Heavy rain halted his locomotive at Utopia Station, forcing him to stay at the Irises Hotel. There, Tracey knocked on his door and confessed to a murder, making Wendel her witness. On the return journey from the hospital he noticed the word "Utopia" through a hole in the rain-wet document, read the report, and departed for the locomotive the next morning; he subsequently reported the experience to MI9. Officer Biles later delivered a subpoena summoning him to testify. Two weeks later he mysteriously entered Utopia through MI9 headquarters'' washroom, and later woke to find himself back at headquarters.', null, 5, null, ARRAY['Wendel'], ARRAY[7], ARRAY['book-one', 'mi9', 'intelligence-officer', 'utopia', 'sequence-7'], 218),
  ('npc-elland-kag', 'Elland Kag — Captain of the White Agate', 'npc', 'Elland Kag, also called Just Elland, is the captain of the passenger ship White Agate. A male human of the Loen Kingdom, he formerly served as boatswain on the Imperial Navy''s William V before leaving the fleet and secretly joining MI9. His captaincy provides the cover through which he monitors sea routes. The corpus identifies him as a Sequence 8 Sheriff. Elland is a middle-aged man who wears a thick dark-red coat, white slacks, and the era''s standard ship-shaped hat; wrinkles mark his eyes, forehead, and mouth. He has an unnamed daughter and counts Oz Kent as a friend. At Damir Harbor, he paid the compensation White Shark requested from Gehrman Sparrow. After the White Agate encountered Red Skull pirates, Elland docked at Bansy Harbor to report the incident to the Navy and Church. In the Storm Cathedral he found a bloody scene and was rescued by Gehrman. During Bayam''s curfew, he recruited Gehrman and Danitz to aid military and Church searches, introduced Gehrman to Oz Kent, and helped Urdi Branch recover plundered goods at a fair price.', null, 5, null, ARRAY['Elland Kag'], ARRAY[8], ARRAY['book-one', 'white-agate', 'mi9', 'imperial-navy', 'sea-routes', 'sequence-8'], 198),
  ('npc-orpheus', 'Orpheus — Singer of the Golden Dream', 'npc', 'Singer Orpheus is a male human pirate from the Intis Republic and the Second Mate of the Golden Dream Pirates. He serves under Edwina Edwards, Vice Admiral Iceberg, and the corpus names the Golden Dream Pirates as both his allies and affiliation. Orpheus is a Sequence 6 Notary. He has deep sculpted outlines and resplendent blond hair. His recorded bounty is 5,500 pounds. Anderson Hood remarks that Orpheus speaks as though singing, which accords with the "Singer" alias used by the corpus. Like most of the Golden Dream Pirates, Orpheus has a crush on Edwina and considers her his "sun." When Edwina disappeared because of Groselle''s Travels, Orpheus joined the other Golden Dream Pirates in seeking Gehrman Sparrow''s help to find her. The source does not give him a residence, family, or separate command, and it does not describe later outcomes for the search. His role is consequently best grounded as a Golden Dream second mate: a named pirate officer, part of the crew''s appeal to Gehrman after their captain''s disappearance, rather than an independently documented leader or adversary.', null, 5, null, ARRAY['Orpheus'], ARRAY[6], ARRAY['book-one', 'golden-dream-pirates', 'pirate', 'intis-republic', 'sequence-6'], 188),
  ('npc-millet', 'Millet — The Fallen Bishop of Bansy Harbor', 'npc', 'Millet was a male human bishop of Bansy Harbor''s Church of the Lord of Storms and a Sequence 6 Wind-blessed. He betrayed that Church to become a believer of the God of Weather native to Bansy Harbor, with his orthodox Church affiliation marked as former. He led the harbor''s heretics after ancient customs revived, including live sacrifice and the consumption of sacrificial flesh and blood. Priest Jayce discovered signs of those customs and reported them to Bishop Millet without knowing that Millet led the heretics. Millet killed Jayce with a wind blade in the cathedral and tried to dispose of the body. Servants then discovered the scene: some became monsters, while others hid underground with priests. Millet fled with the heretics to a mountaintop altar. Mandated Punishers recovered Sealed Artifacts and fought the group; Millet escaped while the other heretics defended the overrun altar. He ultimately encountered Elland and Gehrman Sparrow''s group and was killed by Gehrman Sparrow in the confrontation. The corpus describes him as a pale, wheezing middle-aged man in a dark-blue bishop''s robe embroidered with the storm symbol.', null, 5, null, ARRAY['Millet'], ARRAY[6], ARRAY['book-one', 'bansy-harbor', 'church-of-the-lord-of-storms', 'god-of-weather', 'deceased', 'sequence-6'], 238),
  ('npc-hamilton', 'Hamilton — White Shark of Flying Fish & Wine', 'npc', 'White Shark Hamilton is a male human who owns the Flying Fish & Wine bar in Damir Harbor. The corpus identifies him as a Sequence 9 Sailor and describes his background as shady because of his connections with many pirate factions. He lives at 1 Sea Wall Avenue in Damir Harbor. Hamilton is large, heavyset, tall, and broad, with fair skin; the source compares him to a massive white shark washed ashore. At the time described, white bandages wrapped his forehead, tissue filled his nostrils, and bruises covered his face. While the White Agate resupplied at the harbor, Gehrman Sparrow taught Sea Eagle Logan and the bartender a harsh lesson. Hamilton subsequently approached Elland Kag for half the repair cost of the damaged bar counter, and Elland paid a few soli. Gehrman later disguised himself as one of the bar''s bouncers and questioned Hamilton to gather pirate information. Hamilton disclosed that he maintained contact with many pirates, exchanging their plunder for supplies, alcohol, weapons, and women, and relayed urgent intelligence by radio transceiver to Silver Coin Viper Oder and Old Quinn.', null, 5, null, ARRAY['Hamilton'], ARRAY[9], ARRAY['book-one', 'damir-harbor', 'flying-fish-and-wine', 'pirate-contact', 'sequence-9'], 235),
  ('npc-mr-harry', 'Mr. Harry — Darkwill''s Speaking Owl', 'npc', 'Mr. Harry is a living owl and Darkwill''s pet. The corpus identifies him as a Sequence 9 Spectator and records Darkwill as his master. Darkwill gave the bird the Spectator potion, transforming him into a creature with extraordinary ability, including the capacity to speak and read. Mr. Harry is physically described only as a round-eyed owl. He insists on politeness when questioned, telling Darkwill to call him "Mr. Harry." The source''s history begins with Darkwill wanting a pet that could help against monsters and gangsters. Darkwill searched for ingredients for a potion recipe corresponding to a dragon, but those efforts ended with him obtaining an owl instead. The corpus does not provide Mr. Harry''s origin, residence, family, later exploits, or a separate affiliation. Nor does it explain the exact circumstances in which Darkwill administered the potion beyond the direct statement that he gave it to his pet. The secure account is therefore a narrow one: an owl made extraordinary by Darkwill''s potion, capable of speech and reading, with a notably formal preference for how others address him. He remains alive in the source record.', null, 5, null, ARRAY['Mr. Harry'], ARRAY[9], ARRAY['book-one', 'beyonder-creature', 'owl', 'darkwill', 'sequence-9'], 239),
  ('npc-mr-franky', 'Mr. Franky — Landlord of Iron Cross Street', 'npc', 'Mr. Franky is the landlord of a terrace apartment on Iron Cross Street in Tingen City, where the Moretti family rents a room at the beginning of the story. A short, thin gentleman, he dresses in a top hat, vest, and black suit. His position is defined by the rules he sets for his tenants: rent must be paid, and he makes clear that he will not tolerate arrears. The Morettis know him well enough that he becomes the target of their jokes over both trivial and serious matters. He is described as greedy and gullible, traits that make him a familiar, occasionally comic presence in the family''s daily life rather than a distant property owner. His apartment supplies the modest domestic setting from which the Morettis begin their Tingen years. For local scenes, Franky can provide a landlord''s practical concerns—rent, repairs, tenants, and neighborhood gossip—while remaining tied to Iron Cross Street and the ordinary pressures of working-class housing.', null, 5, 'tingen', ARRAY['Mr. Franky'], '{}', ARRAY['tingen', 'iron-cross-street', 'landlord', 'moretti-family', 'civilian'], 207),
  ('npc-wendy-smyrin', 'Wendy Smyrin — Owner of Smyrin Bakery', 'npc', 'Wendy Smyrin, also called Mrs. Smyrin, owns Smyrin Bakery in Tingen City. A Southerner, she came to Tingen with her husband more than forty years before the story and has sold bread and pastries there since the beginning of Klein''s memories. She is an elderly married woman, over seventy, with completely grayish-white hair and a genial smile. Her bakery is a small, durable point of warmth in the neighborhood: Klein visits to buy bread and pastries, and she is someone with whom he can talk during those purchases. Her own saying—that delicacies can always cure sorrow—suits the practical kindness attached to her trade. Wendy''s role is rooted in regular custom rather than public importance: a familiar shopkeeper serving food, conversation, and a steady neighborhood presence. She can anchor scenes involving errands, affordable treats, long memory of Tingen residents, or the daily rhythms around the bakery. She is a human ordinary person and bakery owner, with no special abilities or hidden role.', null, 5, 'tingen', ARRAY['Wendy Smyrin'], '{}', ARRAY['tingen', 'smyrin-bakery', 'shopkeeper', 'bread', 'civilian'], 198),
  ('npc-rozanne', 'Rozanne — Blackthorn Receptionist', 'npc', 'Rozanne Adelaide is the civilian receptionist at Blackthorn Security Company, the Nighthawks'' division in Tingen City. At the opening of Book One she is twenty-two, a brown-haired young woman with light-brown eyes who wears a light-green Loen-style dress. Cheerful, talkative, and lazy by her own office''s standards, she is nevertheless marked by the loss of her father, a Nighthawk who died in an accident five years earlier. She took the receptionist''s job after his death, and her feelings about the people around her remain mixed: she respects the Nighthawks but also fears and dislikes the dangers associated with their work. Dunn Smith''s death leaves her less lively than before. Rozanne is later married and has children by 1359. In Tingen scenes she belongs at the company''s front desk, where she can receive visitors, manage routine arrivals, and voice the ordinary staff perspective on the people who come through Blackthorn''s doors. Her dossier concerns the receptionist herself, not any separate dream identity.', null, 5, 'tingen', ARRAY['Rozanne'], '{}', ARRAY['tingen', 'blackthorn-security-company', 'receptionist', 'nighthawks', 'civilian'], 205),
  ('npc-maury-macht', 'Maury Macht — Member of Parliament', 'npc', 'Maury Macht is a Member of Parliament in the Loen Kingdom''s House of Commons and the father of Hazel Macht. A married man in his forties, he has black hair, brown eyes, a receding hairline, and a thin, long face. He lives in Backlund, with addresses at 39 Böklund Street and Moose Manor in the northwestern suburbs. Before politics, Macht served as an Army Major in the Loen military; after being discharged, he began a political career in Backlund. He belongs to the New Party, attends the East Balam Military Veterans Mess, and follows the Evernight Goddess. The account credits him with a significant part in efforts to improve the environment. As Dwayne Dantès''s neighbor on Böklund Street and a member of military officer clubs, he introduces Dantès to business cooperation with the military. Maury is useful in Backlund social scenes as a respectable politician and former officer: a host or neighbor whose parliamentary connections, veterans'' circles, and family household join civic life to the capital''s military and commercial networks.', null, 5, 'backlund', ARRAY['Maury Macht'], '{}', ARRAY['backlund', 'parliament', 'new-party', 'veteran', 'macht-family'], 205),
  ('npc-walter', 'Walter — Dwayne Dantès''s Butler', 'npc', 'Walter is Dwayne Dantès''s butler in Backlund, responsible for the male servants and the management of the estate. A married forty-two-year-old man with raven-black hair and stern brown eyes, he brings the caution, old-fashioned manner, and unperturbed bearing expected of his profession. His annual salary is 115 pounds. Walter had previously served Viscount Conrad''s household as land steward and assistant butler, overseeing the viscount''s children. There he earned Prince Edessak Augustus''s regard. Due to certain matters he had a conflict with the household butler while still in service; after Edessak''s death he chose to leave. While working at Viscount Conrad''s household he met a woman through that work, married her, and has a daughter. Walter follows the Evernight Goddess and supports the New Party. Arrodes mentioned to Klein that Walter could lead to further developments, so after an interview Dantès hired him as his butler. Walter remains among the few people truly loyal to Edessak: he cooperated with Trissy''s inquiry into the prince''s death, gathering intelligence openly and offering assistance through his own position. He suits household-management, formal-service, and discreet-investigation scenes in Backlund.', null, 5, 'backlund', ARRAY['Walter'], '{}', ARRAY['backlund', 'butler', 'dwayne-dantes', 'edessak-augustus', 'new-party'], 214),
  ('npc-richardson', 'Richardson — Dwayne Dantès''s Land Steward', 'npc', 'Richardson is a mixed-heritage man, the illegitimate son of a Loenese manor supervisor and an East Balam woman enslaved at the same manor. He was subjected to discrimination and bullying after birth, then selected to serve as a valet before being brought to Backlund. Tall and good-looking, Richardson is silent, submissive, observant, and practiced at noticing useful details; he follows instructions and avoids making decisions on his own. Before entering Dwayne Dantès''s household, he deliberately made mistakes and changed employers repeatedly in an attempt to escape the Eternal Life Society — a Numinous Episcopate branch active in East Borough and Backlund Bridge. His varied service built up experience and caught Butler Walter''s notice. He became Dantès''s valet on a salary of 35 pounds, then was promoted to land steward of Maygur Manor. Officially recorded as affiliated with the Church of the Evernight Goddess and formerly the Eternal Life Society, Richardson is in truth a secret believer in Death (Salinger). His background supports scenes of domestic service, estate work, hard-earned caution, and intelligence gathered by someone who has learned to watch a room closely.', null, 5, 'backlund', ARRAY['Richardson'], '{}', ARRAY['backlund', 'dwayne-dantes', 'maygur-manor', 'land-steward', 'valet', 'eternal-life-society', 'death-salinger'], 213),
  ('npc-old-kohler', 'Old Kohler — East Borough Informant', 'npc', 'Old Kohler, whose true name is Kohler, is a middle-aged Backlund man who becomes Sherlock Moriarty''s informant in the East Borough. He has grizzled gray hair, an obvious beard, and wears a thick jacket. Once a shoemaker with a reasonably good life, he lost his job, wealth, and family after an infectious disease took his wife, son, and daughter. Homeless in the East Borough, he is first noticed by Sherlock while eating a thoroughly nibbled apple core; Sherlock takes pity on him and invites him to a café. With Sherlock''s help, Kohler gains decent dock work and supplies information from the borough. His circumstances begin to improve, and he looks forward to a new life, but he dies in December 1349 during the Great Smog of Backlund. His epitaph remembers him simply as a good worker with a wife, son, and daughter who worked hard to live. Kohler grounds scenes in the poverty, precarious labor, and human cost borne by ordinary residents of the East Borough.', null, 5, 'backlund', ARRAY['Old Kohler'], '{}', ARRAY['backlund', 'east-borough', 'informant', 'dock-worker', 'great-smog'], 205),
  ('npc-aaron-ceres', 'Aaron Ceres — Surgeon of Backlund', 'npc', 'Aaron Ceres is a well-known surgeon in Backlund who owns a private hospital serving high society. He lives at 3 Burningham Road in Hillston Borough with his wife, Wilma Gladys, and their son, Will Ceres. Tall and thin, he wears gold-rimmed glasses and has a cold appearance. Aaron is a believer in the Evernight Goddess and belongs to the Quelaag Club. Mary Gale recommends Sherlock Moriarty to him, and Aaron is one of the recommenders who helps introduce Sherlock to that club. His professional manner is dryly expressed in his remark that people would not wish to meet a surgeon very often. Aaron seeks Sherlock''s advice after a long period of misfortune and nightmares, follows the recommendation to speak with the cathedral bishop, and reports that the problem is resolved. He later hires Sherlock concerning a former young patient and a disturbing dream, and eventually tells him that Wilma is pregnant. As his family grows, Aaron finds that his practice and income improve. He is a useful Backlund contact for medical, club, and respectable-professional scenes.', null, 5, 'backlund', ARRAY['Aaron Ceres'], '{}', ARRAY['backlund', 'surgeon', 'quelaag-club', 'hillston-borough', 'hospital'], 227),
  ('npc-mary-schott', 'Mary Schott — Coim Company Director', 'npc', 'Mary Schott, formerly Mary Gale, is the divorced executive director and a major shareholder of Backlund''s Coim Company. Her wealth amounts to tens of thousands, and she holds a seat on the National Atmospheric Pollution Council as well as membership in the Quelaag Club. She lives in Backlund, follows the Evernight Goddess, and is a friend of Stelyn Sammer, Aaron Ceres, Talim Dumont, and Hibbert Hall. Mary''s father co-founded Coim Company and held a twenty-percent stake when it was a small firm. As Backlund''s pollution worsened and demand for anthracite and charcoal rose, the business expanded into one of the capital''s ten leading industrial companies, greatly increasing her wealth. When she suspected her husband Doragu Gale of adultery, she hired Sherlock Moriarty to obtain evidence needed for a divorce without splitting the company shares. She then introduced Sherlock to Aaron Ceres and Talim Dumont for Quelaag Club sponsorship. Later she seeks his advice over a threatening letter and conducts a share transaction with Dwayne Dantès. Mary fits commercial, civic, and upper-middle-class Backlund scenes.', null, 5, 'backlund', ARRAY['Mary Schott'], '{}', ARRAY['backlund', 'coim-company', 'quelaag-club', 'business', 'pollution-council'], 211),
  ('npc-talim-dumont', 'Talim Dumont — Equestrian Teacher', 'npc', 'Talim Dumont is an aristocratic equestrian teacher in Backlund and a friend of Prince Edessak Augustus. Born to a family whose grandfather held a viscount''s title, Talim used that standing to teach the sons of nobles and became acquainted with the prince through his work. He belongs to the Quelaag Club and introduced Sherlock Moriarty to it at Mary Gale''s request. Talim also brought Sherlock practical work: when Daily Observer reporter Mike Joseph needed protection during an investigation in the East Borough, Talim connected the two after testing Sherlock''s combat ability. He later sought Sherlock''s help on Prince Edessak''s behalf concerning an organization marked by tarot cards, and introduced Framis Cage over a bicycle-company investment. Talim suffered signs of a curse and died suddenly in front of Sherlock on December 18, 1349. Afterward, Edessak asked Sherlock to investigate his friend''s death.', null, 5, 'backlund', ARRAY['Talim Dumont'], '{}', ARRAY['backlund', 'equestrian-teacher', 'quelaag-club', 'aristocrat', 'deceased'], 199),
  ('npc-mike-joseph', 'Mike Joseph — Daily Observer Reporter', 'npc', 'Mike Joseph is a reporter for the Daily Observer in Backlund. A man in his late twenties with blue eyes, sparse eyebrows, rough skin, and a thin mustache, he is described as righteous despite being stingy and a capable actor. His reporting on a serial-killer case identified what the victims had in common, warning people who might share those circumstances. Talim Dumont introduced Mike to Sherlock Moriarty when Mike needed to investigate the case; Mike hired Sherlock as protection for a trip to the Golden Rose in the East Borough. His editor later assigned him further work in the East Borough, dock area, and factory district, for which he again retained Sherlock. Following Capim''s case, Mike urged the government through his reporting to turn Capim''s estate into a bursary fund for rescued girls and other people harmed by Capim. Klein also sent him an anonymous letter asking for support for Daisy after the Great Smog.', null, 5, 'backlund', ARRAY['Mike Joseph'], '{}', ARRAY['backlund', 'daily-observer', 'reporter', 'investigation', 'journalism'], 205),
  ('npc-stelyn-sammer', 'Stelyn Sammer — Minsk Street Landlady', 'npc', 'Stelyn Sammer, also called Mrs. Sammer, is the landlady of Unit 15 Minsk Street in Cherwood Borough, Backlund. She lives with her family in the neighboring Unit 17 and rented the terrace house at Unit 15 to Sherlock Moriarty for 25 pounds per half year. Stelyn is married to Luke Sammer, a Coim Company manager and member of the Kingdom''s Soot Reduction Association; they have twin children, a son and a daughter. A blonde, blue-eyed woman in her thirties, she values a high quality of life and often displays her sense of superiority, but the account also calls her a kind landlady. When Sherlock fought Meursault in Unit 15, she did not seek compensation from him. Stelyn is Mary Gale''s friend and directed Mary to Sherlock when she needed help. During the 1350 World War, famine throughout Backlund drove Stelyn to sell her body to an old rich man in order to obtain bread for her children.', null, 5, 'backlund', ARRAY['Stelyn Sammer'], '{}', ARRAY['backlund', 'landlady', 'minsk-street', 'cherwood-borough', 'sammer-family'], 207),
  ('npc-elizabeth', 'Elizabeth — Ivos Public School Student', 'npc', 'Elizabeth is a student at Ivos Public School in Tingen City and a former schoolmate of Melissa Moretti. About fifteen years old at her debut, she has naturally curly brown hair, light-blue eyes, and an adorable face with baby-fat cheeks. Her middle-class family owns an estate in Lamud Town. Elizabeth is friends with Selena Wood and Melissa, and she is affiliated with the Church of the Evernight Goddess. Her interest in mysticism led Selena to introduce her to Tingen''s underground market, where Elizabeth met Klein Moretti and asked his advice on choosing a protection amulet as a birthday gift for Selena. At Selena''s banquet, she learned that Klein was Melissa''s second brother and assisted him during the magic-mirror incident. On a vacation near Lamud Town, Elizabeth visited an abandoned ancient castle on a mountain, then suffered a nightmare of a knight in full black armor chasing her. She sought Klein at the Divination Club and asked him to interpret the dream.', null, 5, 'tingen', ARRAY['Elizabeth'], '{}', ARRAY['tingen', 'ivos-public-school', 'student', 'lamud-town', 'melissa-moretti'], 196),
  ('npc-orianna', 'Orianna — Blackthorn Accountant', 'npc', 'Orianna, commonly called Mrs. Orianna, is an accountant at the Blackthorn Security Company in Tingen City. A married woman in her thirties with black hair, green eyes, and fashionable curly hair, she is affiliated with the Church of the Evernight Goddess. Sixteen years before the account''s present events, Orianna was studying accountancy at business school when the serial killer known as the Bloody Butcher murdered five girls in Tingen. She nearly became the sixth victim, but the Nighthawks arrived in time; afterward, she worked as Blackthorn Security Company''s accountant. Klein describes her as delicate and gentle, someone who pursues an exquisite life and quietly takes good care of people. She rarely rejects Old Neil''s expense claims, however implausible their stated reasons, instead leaving the decision to the captain. Rozanne likewise considers Orianna affable and easy to get along with. Orianna''s father is a watch smith noted for his excellent skill.', null, 5, 'tingen', ARRAY['Orianna'], '{}', ARRAY['tingen', 'blackthorn-security-company', 'accountant', 'evernight-goddess', 'civilian-staff'], 190),
  ('npc-jurgen-cooper', 'Jurgen Cooper — Senior Solicitor', 'npc', 'Jurgen Cooper is a young senior solicitor and formerly Sherlock Moriarty''s neighbor at Unit 58 Minsk Street in Backlund. He lives with his grandmother, Madam Doris, and their cat Brody. Jurgen is serious, meticulous, and notably humorless; he maintains a formal manner and dress even in ordinary circumstances, typically wearing a black double-breasted coat, half top hat, and bow tie. Sherlock''s first detective job came from Jurgen and Doris, who hired him to find Brody; after Sherlock succeeded, the two became friends. Jurgen later appeared at the police station to bail Sherlock out pro bono after the Meursault case, hoping to cultivate the kind of working relationship solicitors often maintain with private detectives. He subsequently helped Sherlock with an arms-possession matter and drafted an investment contract for Sherlock''s bicycle-company shares. When Doris''s chronic lung problems required hospital care and healthier air, Jurgen left Backlund with her for Desi Bay in the south.', null, 5, 'backlund', ARRAY['Jurgen Cooper'], '{}', ARRAY['backlund', 'solicitor', 'minsk-street', 'madam-doris', 'brody'], 198),
  ('npc-alice-moretti', 'Alice Moretti — Benson Moretti''s Daughter', 'npc', 'Alice Moretti is the daughter of Benson Moretti and Lucy Brook, and the niece of Klein and Melissa Moretti. She is a human girl of the Moretti family in Backlund who appears alongside Melissa in the final chapter of Book 1. Her family is affiliated with the Church of the Fool. Alice is also the narrator of the Audio Drama special episode Klein''s Niece, in which the Moretti family''s conversion to the Church of the Fool is confirmed and Alice is presented as a friend of Leonard Mitchell and Will Auceptin. The corpus records no occupation, sequence, or broader biographical history for her. Her dossier therefore remains limited to her named family connections, Backlund setting, Book 1 appearance, and the later audio-drama narration.', null, 5, 'backlund', ARRAY['Alice Moretti'], '{}', ARRAY['backlund', 'moretti-family', 'benson-moretti', 'book-one', 'audio-drama'], 168),
  ('npc-bredt', 'Bredt — Blackthorn Civilian Staffer', 'npc', 'Bredt is a married civilian staff member of the Blackthorn Security Company in Tingen City. A middle-aged man with a thick black beard, he is affiliated with the Church of the Evernight Goddess and lives with his unnamed wife. He is described as the best report writer among Blackthorn''s clerks, a romantic gentleman who has continued to love his wife after fifteen years of marriage. Bredt''s guiding maxim is that the less a person knows, the longer that person lives; he attributes it to a dying Beyonder who warned him never to investigate strange and dangerous matters. This cautious outlook shapes the quiet, administrative role recorded for him at Blackthorn. The company is his listed affiliation, and the corpus places his residence in Tingen City. Beyond his work as civilian staff, his marriage, appearance, report-writing reputation, and deliberately limited approach to dangerous knowledge, the source gives no wider role or extraordinary abilities for Bredt.', null, 5, 'tingen', ARRAY['Bredt'], '{}', ARRAY['tingen', 'blackthorn-security-company', 'civilian-staff', 'clerk', 'report-writer'], 184),
  ('npc-cesare-francis', 'Cesare Francis', 'npc', 'Cesare Francis is a human civilian employee of Tingen''s Blackthorn Security Company. He serves as the company''s clerk, responsible for procuring necessities and collecting supplies. The company also relies on him as its carriage driver. A description attributed to the Captain explains why these errands fall to Cesare: although he is civilian staff, his work repeatedly puts him near dangerous situations, and he keeps such a low profile that this may have helped him survive. He is affiliated with Blackthorn Security Company, resides in Tingen City, and follows the Church of the Evernight Goddess. Cesare''s duties are practical rather than glamorous: purchases, applications, supplies, and transport are entrusted to him. That makes him a useful point of contact when routine office business, a carriage, or discreet procurement is needed, while the record does not assign him any extraordinary office or ability.', null, 5, 'tingen', ARRAY['Cesare Francis'], '{}', ARRAY['blackthorn-security-company', 'clerk', 'tingen', 'book-one'], 191),
  ('npc-glacis', 'Glacis', 'npc', 'Glacis is a human resident of Tingen City and a novice fortune-teller at the Divination Club. He is skilled in tarot divination and charges two pence for each reading. Around thirty years old, he has light yellow hair, dark green eyes, and a preference for a white shirt and black vest; a monocle hangs from his chest. He is married and belongs to the Divination Club. Klein Moretti first chose Glacis for a tarot reading while considering how to proceed with his own work. During that meeting, Klein noticed Glacis''s lung trouble and advised him to see a doctor; the diagnosis was pneumonia, later treated with medicine obtained through Glacis''s wife. Glacis later sought a reading about an iron-mine investment connected to Lanevus. He invested only a third of the amount he had first considered, learned that Lanevus was a cheat, and afterward introduced Madam Christina to Klein.', null, 5, 'tingen', ARRAY['Glacis'], '{}', ARRAY['divination-club', 'fortune-teller', 'tarot', 'tingen', 'book-one'], 192),
  ('npc-travis-everett', 'Travis Everett', 'npc', 'Travis Everett is a human superintendent at the police headquarters of Le Marché du Quartier du Gentleman in Trier, holding one of the highest positions for carrying out tasks at that headquarters. About thirty years old and nearly 1.75 meters tall, he has short black hair, blue eyes, large black-framed glasses, and a slightly broad chin. He follows the Church of the Eternal Blazing Sun. Baron Brignais enjoys conversing with Everett, and Emperor Roselle''s words describe him as the epitome of a "Mr. Nice Guy": he prefers not to delve into the truth, simply hoping for harmonious interactions and a lack of trouble. Despite this disposition, he possesses a remarkable ability to resolve conflicts among the mobs in the market district. He tells Baron Brignais that any disputes can be brought to him for a tribunal, framing his public role as a conciliator within Trier''s police administration.', null, 5, 'trier', ARRAY['Travis Everett'], '{}', ARRAY['police-department', 'superintendent', 'trier', 'book-two'], 197),
  ('npc-flameng', 'Flameng', 'npc', 'Flameng was a human tenant of Room 310 in Trier''s Auberge du Coq Doré Hotel. A former university lecturer with expertise in minerals, he was known at the hotel as an occasionally lucid madman. He had black hair, blue eyes, and an unshaven bushy black beard; his age is given as about twenty, though the page''s appearance description calls him late twenties. He was widowed and had lost his child, parents, and wife. After leaving the Museum of Mineralogy and Pathology in the Catacomb de Trier, he began to feel watched. His child then became gravely ill and died, his wife died by suicide, and his father killed his mother before taking his own life. Flameng subsequently suffered a terminal illness and had difficulty remembering events, sometimes waking in the hotel without knowing how he had moved there. He later died by suicide in his room, leaving a note asking to be laid to rest in the Underground Tomb of Lights within the catacombs.', null, 5, 'trier', ARRAY['Flameng'], '{}', ARRAY['auberge-du-coq-dore-hotel', 'former-university-lecturer', 'minerals', 'trier', 'book-two'], 218),
  ('npc-ruhr', 'Ruhr', 'npc', 'Ruhr was a human resident of Room 302 at Trier''s Auberge du Coq Doré Hotel, where he lived with his wife Michel. The couple were swindlers: they sold packets represented as pornographic material, but the packets actually held photographs of the Srenzo River and of Trier''s castles and palaces. At night they scavenged, visiting waste-disposal sites for discarded objects that might retain value and storing them in their room. Ruhr and Michel had arrived in Trier young, worked various jobs, lost their child, and struggled on meager wages. As they aged, they saved money in hopes of returning to Aurmir, Champagne Province, to buy ten acres for grape cultivation. Ruhr fell suddenly ill after salvaging items from a parliament member''s office banquet. Michel sought help carrying him to a clinic; his condition improved briefly after treatment, but he died in his sleep. The police later classified the case as death due to illness and suicide.', null, 5, 'trier', ARRAY['Ruhr'], '{}', ARRAY['auberge-du-coq-dore-hotel', 'swindler', 'scavenger', 'trier', 'book-two'], 218),
  ('npc-michel', 'Michel', 'npc', 'Michel was a human tenant of Room 302 in Trier''s Auberge du Coq Doré Hotel and the wife of Ruhr. Together they ran a small fraud, selling packets advertised as pornographic materials that instead contained photographs of the Srenzo River and images of Trier''s castles and palaces. They also scavenged at night, gathering discarded items with possible value and hoarding them in their room. Michel and Ruhr came to Trier when young, worked assorted jobs, lost their child, and struggled with low wages and declining health. They saved what they could with the hope of returning to Aurmir in Champagne Province and buying ten acres for grape cultivation. When Ruhr fell ill after collecting discarded items, Michel asked Ciel to help carry him to a clinic. Ruhr later died in his sleep. Michel then lost her will to live. She spent their savings on a final meal for him, burned their banknotes while singing, and died by suicide in their room. Her remembered song begins, "In the Capital of Joy, forever Trier!"', null, 5, 'trier', ARRAY['Michel'], '{}', ARRAY['auberge-du-coq-dore-hotel', 'swindler', 'scavenger', 'trier', 'book-two'], 225),
  ('npc-cassandra', 'Cassandra', 'npc', 'Cassandra is a human woman and member of Hugues Artois''s campaign in Trier. She is a descendant of the Sauron Family. Her known associates include Tybalt Jacques, Rhône, Boduva, and Margaret; Hugues Artois is her listed master. She has fiery red hair and is rumored to possess noble lineage. Her features show chiseled lines, though her overall beauty carries an air of neutrality. Cassandra is classified as a Boon Recipient — she is recorded directly referencing a boon called the Orator, granted by an unnamed individual. The source gives her vital status as alive and places her among Book Two characters in the Intis Republic and Trier. No residence, occupation, religion, or personal sequence pathway is recorded. Her role is political and social: participation in Hugues Artois''s campaign circle, with no independent public office or settled biography beyond her lineage, appearance, named network, and boon-recipient status.', null, 5, 'trier', ARRAY['Cassandra'], '{}', ARRAY['hugues-artois-campaign', 'sauron-family', 'trier', 'book-two', 'boon-recipient'], 210),
  ('npc-gabriel', 'Gabriel', 'npc', 'Gabriel was a human playwright in Trier who specialized in writing plays for theaters. Although he considered himself talented, theater managers repeatedly refused to give him an opportunity, so he accepted tabloid requests and wrote ordinary stories to pay his rent. He first lived in Room 206 of the Auberge du Coq Doré Hotel, next door to Ciel, and later moved to Room 504 at 34 Rue Saint-Michel in Quartier 2. He was a lanky young man, barely 1.7 meters tall, with unkempt brown hair, dark-brown eyes, oversized black-framed glasses, a faded linen shirt, and black suspenders. Lumian met Gabriel in an underground bar after another rejection. With Jenna, they forced theater manager Nathan Lopp to hear Gabriel read a script; after the first scene, Lopp accepted it, signed a contract, and purchased the work. Gabriel later visited Séraphine before leaving the hotel, and he ultimately died with her in a world of painting. His script was titled "Lightseeker."', null, 5, 'trier', ARRAY['Gabriel'], '{}', ARRAY['playwright', 'auberge-du-coq-dore-hotel', 'trier', 'book-two'], 207)
