-- Seed Batch 4 lore (missing NPC audit): city-level non-Beyonder color/
-- plot-hook NPCs (city-keyed, sequences '{}') + no-active-city Sequence 5-9
-- Beyonders (RAG-only: no city, no pathway). Generated from the canonical TS
-- source (src/lib/lore/npcs.ts). narratorOnly is a TS-only prompt flag (no
-- column), not persisted. All entries pathway-less. Arrays seed as '{}'.

on conflict (slug) do update set
  title = excluded.title,
  category = excluded.category,
  content = excluded.content,
  pathway = excluded.pathway,
  epoch = excluded.epoch,
  city = excluded.city,
  npcs = excluded.npcs,
  sequences = excluded.sequences,
  tags = excluded.tags,
  token_count = excluded.token_count;
